"""Copy the SDL3 and wgpu bindings from Odin's vendor directory into third_party/odin/,
rewriting only the foreign-import blocks so they link the static libraries in third_party/prebuilt/.

Usage: python3 -I sync_bindings.py <odin root> <third_party dir>
"""

import pathlib
import shutil
import sys

odin_root = pathlib.Path(sys.argv[1])
third_party = pathlib.Path(sys.argv[2])
vendor = odin_root / "vendor"
out = third_party / "odin"

HEADER = (
    "// myod: generated by third_party/scripts/sync_bindings.py.\n"
    "// Bindings come from Odin's vendor package; only the foreign imports were rewritten to point at third_party/prebuilt/.\n"
)


def copy_package(name, skip=()):
    src = vendor / name
    dst = out / name
    if dst.exists():
        shutil.rmtree(dst)
    dst.mkdir(parents=True)
    for f in sorted(src.glob("*.odin")):
        if f.name in skip:
            continue
        shutil.copy2(f, dst / f.name)
    return dst


# ---- SDL3 ----

sdl3 = copy_package("sdl3")
(sdl3 / "sdl3__foreign.odin").write_text(HEADER + """
package sdl3

// System libraries needed to link SDL3 statically, taken from the Libs field of sdl3.pc in the SDL build output.
when ODIN_OS == .Darwin && ODIN_ARCH == .arm64 {
	@(export) foreign import lib {
		"../../prebuilt/macos-arm64/libSDL3.a",
		"system:CoreMedia.framework",
		"system:CoreVideo.framework",
		"system:Cocoa.framework",
		"system:UniformTypeIdentifiers.framework",
		"system:IOKit.framework",
		"system:Carbon.framework",
		"system:Foundation.framework",
		"system:Metal.framework",
		"system:QuartzCore.framework",
		"system:pthread",
		"system:m",
	}
} else when ODIN_OS == .Linux && ODIN_ARCH == .amd64 {
	@(export) foreign import lib {
		"../../prebuilt/linux-x86_64/libSDL3.a",
		"system:pthread",
		"system:m",
		"system:dl",
	}
} else when ODIN_OS == .Linux && ODIN_ARCH == .arm64 {
	@(export) foreign import lib {
		"../../prebuilt/linux-arm64/libSDL3.a",
		"system:pthread",
		"system:m",
		"system:dl",
	}
} else {
	#panic("myod does not support this platform yet: only macOS arm64, Linux x86_64 and Linux arm64")
}
""")

# ---- wgpu ----

wgpu = copy_package("wgpu", skip=("wgpu_js.odin",))
wgpu_main = wgpu / "wgpu.odin"
text = wgpu_main.read_text()

begin = text.index("WGPU_SHARED :: #config")
end_marker = '\tforeign import libwgpu "wgpu"\n}\n'
end = text.index(end_marker) + len(end_marker)

replacement = """when ODIN_OS == .Darwin && ODIN_ARCH == .arm64 {
	@(export)
	foreign import libwgpu {
		"../../prebuilt/macos-arm64/libwgpu_native.a",
		"system:Foundation.framework",
		"system:CoreFoundation.framework",
		"system:QuartzCore.framework",
		"system:Metal.framework",
	}
} else when ODIN_OS == .Linux && ODIN_ARCH == .amd64 {
	@(export)
	foreign import libwgpu {
		"../../prebuilt/linux-x86_64/libwgpu_native.a",
		"system:dl",
		"system:m",
	}
} else when ODIN_OS == .Linux && ODIN_ARCH == .arm64 {
	@(export)
	foreign import libwgpu {
		"../../prebuilt/linux-arm64/libwgpu_native.a",
		"system:dl",
		"system:m",
	}
} else {
	#panic("myod does not support this platform yet: only macOS arm64, Linux x86_64 and Linux arm64")
}
"""

text = text[:begin] + replacement + text[end:]
assert "#config(WGPU_SHARED" not in text
wgpu_main.write_text(HEADER + text)

print(f"synced bindings into {out}")
